// Process uploaded files and extract audio data
const items = $input.all();
const processedItems = [];

for (const item of items) {
  if (item.binary && Object.keys(item.binary).length > 0) {
    // Process each uploaded file
    for (const [fileName, fileData] of Object.entries(item.binary)) {
      // Check if it's an audio file
      const mimeType = fileData.mimeType || '';
      const isAudio = mimeType.startsWith('audio/') || 
                     fileName.toLowerCase().endsWith('.wav') ||
                     fileName.toLowerCase().endsWith('.mp3') ||
                     fileName.toLowerCase().endsWith('.m4a') ||
                     fileName.toLowerCase().endsWith('.ogg');

      if (isAudio) {
        const callid = `chat-audio-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

        processedItems.push({
          json: {
            callid: callid,
            filename: fileName,
            mimeType: mimeType,
            fileSize: fileData.fileSize || 0,
            uploadTime: new Date().toISOString(),
            userInput: item.json.text || '' // User's text message if any
          },
          binary: {
            audio: fileData
          }
        });
      }
    }
  } else if (item.json.text) {
    // Handle text-only input
    return [{
      json: {
        error: 'No audio file detected. Please upload an audio file for analysis.',
        message: item.json.text
      }
    }];
  }
}

if (processedItems.length === 0) {
  return [{
    json: {
      error: 'No valid audio files found in upload. Please upload audio files (WAV, MP3, M4A, OGG).'
    }
  }];
}

return processedItems;

// Base64 encode audio and prepare OpenRouter request
const binaryData = $input.first().binary.audio;
const audioBuffer = Buffer.from(binaryData.data, 'base64');
const base64Audio = audioBuffer.toString('base64');

// Determine audio format from file extension/mime type
const mimeType = $input.first().json.mimeType;
const filename = $input.first().json.filename.toLowerCase();
let audioFormat = 'wav';

if (mimeType.includes('mp3') || filename.endsWith('.mp3')) audioFormat = 'mp3';
else if (mimeType.includes('m4a') || filename.endsWith('.m4a')) audioFormat = 'm4a';
else if (mimeType.includes('ogg') || filename.endsWith('.ogg')) audioFormat = 'ogg';
else if (mimeType.includes('webm') || filename.endsWith('.webm')) audioFormat = 'webm';

const messages = [{
  role: 'user',
  content: [
    {
      type: 'text',
      text: `Please transcribe this audio file with detailed speaker diarization. Format response as a JSON array of conversation segments. Each segment should include:\n- speaker: "speaker_0", "speaker_1", etc.\n- text: spoken content\n- start: start time in seconds\n- end: end time in seconds\n\nThe audio file is: ${$input.first().json.filename}\n\nUser also mentioned: ${$input.first().json.userInput || 'No additional context'}`
    },
    {
      type: 'input_audio',
      inputAudio: {
        data: base64Audio,
        format: audioFormat
      }
    }
  ]
}];

return [{
  json: {
    callid: $input.first().json.callid,
    filename: $input.first().json.filename,
    mimeType: $input.first().json.mimeType,
    userInput: $input.first().json.userInput,
    messages: messages,
    audioFormat: audioFormat
  }
}];

// Process OpenRouter transcription response into conversation format
let words = [];
let transcriptionError = null;

const inputItem = $input.first();

if (inputItem.json.error) {
  transcriptionError = inputItem.json.error;
} else {
  try {
    const response = inputItem.json.choices?.[0]?.message?.content;
    if (response) {
      // Try to parse JSON response
      let parsed;
      if (response.includes('```json')) {
        parsed = JSON.parse(response.match(/```json\s*([\s\S]*?)\s*```/)?.[1] || response);
      } else {
        parsed = JSON.parse(response);
      }
      words = parsed || [];
    } else {
      transcriptionError = 'No transcription response received from OpenRouter';
    }
  } catch (error) {
    transcriptionError = 'Failed to parse transcription response: ' + error.message;
    console.log('Transcription Error:', transcriptionError, 'Response:', inputItem.json.choices?.[0]?.message?.content);
  }
}

if (transcriptionError) {
  return [{
    json: {
      callid: inputItem.json.callid,
      filename: inputItem.json.filename,
      userInput: inputItem.json.userInput,
      conversation: [],
      error: transcriptionError
    }
  }];
}

// Format into conversation structure
const conversation = words.map((segment, index) => ({
  speaker: segment.speaker || `speaker_${segment.speaker_id || 0}`,
  text: segment.text || segment.content || '',
  start: segment.start || 0,
  end: segment.end || (segment.start || 0) + 1,
  conversation_index: index
}));

return [{
  json: {
    callid: inputItem.json.callid,
    filename: inputItem.json.filename,
    userInput: inputItem.json.userInput,
    conversation: conversation,
    transcriptSuccess: true
  }
}];

// Create analysis prompt (reuse existing logic)
let conversation;
let callid_from_input = 'unknown';
let userInput = '';

try {
  const inputItem = $input.first().json;
  conversation = inputItem.conversation || [];
  callid_from_input = inputItem.callid || 'unknown';
  userInput = inputItem.userInput || '';

  if (!Array.isArray(conversation)) {
    console.log('Warning: conversation is not an array');
    conversation = [];
  }
} catch (error) {
  console.log('Error (Create Analysis Prompt - conversation):', error.message);
  conversation = [];
}

const promptsystem = `You are a call center conversation analyzer.

Below is a JSON array called conversation, where each item represents a speech block with the following structure:
{
  "speaker": "speaker_0" or "speaker_1" or "unknown",
  "text": "spoken words",
  "start": float (start time in seconds),
  "end": float (end time in seconds),
  "conversation_index": integer (order of conversation)
}

User provided additional context: "${userInput}"

Your task is to analyze this conversation based on the following criteria. Respond with true, false, or "unknown" for boolean questions. For the sale value scale, use an integer from 1 to 5 if a sale occurred, otherwise use 0 or null.

Instructions:
1. Determine which speaker is the call center agent and which is the customer.
2. Analyze the customer's emotional tone (e.g., calm, angry, excited, confused, etc.).
3. Assess overall conversation sentiment (positive, negative, neutral).
4. Identify the main topic (e.g., complaint, sales, technical issue, billing).
5. Extract the most significant term/keyword (e.g., 'approved', 'canceled', 'offer', 'refund').
6. Classify the general experience (acceptable, unacceptable, neutral).
7. Summarize the customer's experience in one word (e.g., frustrating, smooth, excellent).
8. Was an email address asked for or provided?
9. Did any positive comments from the customer pass the sale?
10. Did any negative comments from the customer pass the sale?
11. Was the price negotiated?
12. Was the customer addressed politely?
13. Was the conversation fun/enjoyable?
14. Were service advantages mentioned?
15. Were other platforms mentioned?
16. What was the sale outcome? (sold, not sold, unknown)
17. If sold, rate the sale value scale (1-5).

Please respond with a JSON object containing all these fields with appropriate values.`;

const promtuser = JSON.stringify(conversation, null, 2);

return [{
  json: {
    callid: callid_from_input,
    filename: $input.first().json.filename,
    userInput: userInput,
    conversation: conversation,
    promptsys: promptsystem,
    promtuser: promtuser
  }
}];

// Format LLM response (reuse existing logic)
const llmInputItem = $input.first();
let output = {};
let llmError = null;

const normalizeValue = (val) => {
  return (val === 'unknown' || val === undefined) ? null : val;
};

const defaultFields = {
  sentiment: null,
  topic: null,
  significant_term: null,
  general_value: null,
  general_experience: null,
  email_inquired: null,
  positive_comment_passed_sale: null,
  negative_comment_passed_sale: null,
  price_negotiated: null,
  customer_addressed_politely: null,
  conversation_fun: null,
  service_advantages_mentioned: null,
  other_platforms_mentioned: null,
  sale_outcome: null,
  sale_value_scale: null,
  asked_if_commenters_known: null,
  high_profile_advantages_mentioned: null,
  llm_error_message: null
};

let callid = 'unknown';
try {
  callid = $('Process Transcription').item.json.callid || 'unknown';
} catch (error) {
  console.log('CallID not found:', error.message);
}

if (llmInputItem.json.error) {
  llmError = llmInputItem.json.error.message || 'LLM analysis failed';
  console.log('LLM Error:', llmError);
  output = {
    ...defaultFields,
    llm_error_message: llmError
  };
} else if (llmInputItem.json && llmInputItem.json.text) {
  let responseText = llmInputItem.json.text;

  if (responseText.startsWith('```json')) {
    responseText = responseText.slice(7).trim();
    if (responseText.endsWith('```')) {
      responseText = responseText.slice(0, -3).trim();
    }
  } else if (responseText.startsWith('```')) {
    responseText = responseText.slice(3).trim();
    if (responseText.endsWith('```')) {
      responseText = responseText.slice(0, -3).trim();
    }
  }

  try {
    const parsed = JSON.parse(responseText);
    output = {
      sentiment: normalizeValue(parsed.sentiment) || defaultFields.sentiment,
      topic: normalizeValue(parsed.topic) || defaultFields.topic,
      significant_term: normalizeValue(parsed.significant_term) || defaultFields.significant_term,
      general_value: normalizeValue(parsed.general_value) || defaultFields.general_value,
      general_experience: normalizeValue(parsed.general_experience) || defaultFields.general_experience,
      email_inquired: normalizeValue(parsed.email_inquired) || defaultFields.email_inquired,
      positive_comment_passed_sale: normalizeValue(parsed.positive_comment_passed_sale) || defaultFields.positive_comment_passed_sale,
      negative_comment_passed_sale: normalizeValue(parsed.negative_comment_passed_sale) || defaultFields.negative_comment_passed_sale,
      price_negotiated: normalizeValue(parsed.price_negotiated) || defaultFields.price_negotiated,
      customer_addressed_politely: normalizeValue(parsed.customer_addressed_politely) || defaultFields.customer_addressed_politely,
      conversation_fun: normalizeValue(parsed.conversation_fun) || defaultFields.conversation_fun,
      service_advantages_mentioned: normalizeValue(parsed.service_advantages_mentioned) || defaultFields.service_advantages_mentioned,
      other_platforms_mentioned: normalizeValue(parsed.other_platforms_mentioned) || defaultFields.other_platforms_mentioned,
      sale_outcome: normalizeValue(parsed.sale_outcome) || defaultFields.sale_outcome,
      sale_value_scale: normalizeValue(parsed.sale_value_scale) || defaultFields.sale_value_scale,
      asked_if_commenters_known: normalizeValue(parsed.asked_if_commenters_known) || defaultFields.asked_if_commenters_known,
      high_profile_advantages_mentioned: normalizeValue(parsed.high_profile_advantages_mentioned) || defaultFields.high_profile_advantages_mentioned
    };
  } catch (error) {
    llmError = 'Failed to parse LLM response: ' + error.message;
    console.log('LLM Response Parse Error:', error.message, 'Response:', responseText);
    output = {
      ...defaultFields,
      llm_error_message: llmError
    };
  }
} else {
  llmError = 'No text response from LLM';
  output = {
    ...defaultFields,
    llm_error_message: llmError
  };
}

return [{
  json: {
    callid: callid,
    filename: $('Process Transcription').item.json.filename,
    userInput: $('Process Transcription').item.json.userInput,
    ...output
  }
}];

// Format response for chat interface
const item = $input.first().json;

const sentimentEmoji = {
  'positive': '😊',
  'negative': '😞',
  'neutral': '😐'
};

const saleOutcomeEmoji = {
  'sold': '✅',
  'not sold': '❌',
  'unknown': '❓'
};

const formatBoolean = (val) => {
  if (val === true) return '✓';
  if (val === false) return '✗';
  return '❓';
};

if (item.llm_error_message) {
  return [{
    json: {
      text: `❌ **Call Analysis Failed**\n\nAn error occurred while analyzing the call recording:\n\n\`${item.llm_error_message}\`\n\nPlease try again or contact support.`
    }
  }];
}

const responseText = `🎧 **Call Analysis Complete**\n\n**📋 Call ID:** ${item.callid}\n**📁 File:** ${item.filename}\n\n**🎯 Topic:** ${item.topic || 'N/A'}\n**💭 Sentiment:** ${item.sentiment || 'N/A'} ${sentimentEmoji[item.sentiment?.toLowerCase()] || ''}\n**⚡ Key Term:** ${item.significant_term || 'N/A'}\n**📊 Experience:** ${item.general_experience || 'N/A'}\n**💰 Sale Outcome:** ${item.sale_outcome || 'N/A'} ${saleOutcomeEmoji[item.sale_outcome?.toLowerCase()] || ''}\n**📈 Sale Value:** ${item.sale_value_scale || 'N/A'}/5\n\n**📋 Key Indicators:**\n• Email Inquired: ${formatBoolean(item.email_inquired)}\n• Price Negotiated: ${formatBoolean(item.price_negotiated)}\n• Customer Addressed Politely: ${formatBoolean(item.customer_addressed_politely)}\n• Conversation Fun: ${formatBoolean(item.conversation_fun)}\n• Service Advantages: ${formatBoolean(item.service_advantages_mentioned)}\n• Positive Comment Passed Sale: ${formatBoolean(item.positive_comment_passed_sale)}\n• Negative Comment Passed Sale: ${formatBoolean(item.negative_comment_passed_sale)}\n\n${item.userInput ? `**💬 User Context:** ${item.userInput}\n\n` : ''}✨ **Analysis completed successfully!**`;

return [{
  json: {
    text: responseText
  }
}];
